    return json.loads((folder(symbol) / "samples" / f"{case}.json").read_text(encoding="utf-8"))


def symbols() -> list[str]:
    """Every contract folder."""
    return sorted(p.name for p in ROOT.iterdir() if p.is_dir() and "." in p.name)


def contract_symbol(symbol: str) -> Any:
    """The object a folder freezes: ``core.WorldSpec`` is ``rllab.core.WorldSpec``."""
    component, name = symbol.split(".", 1)
    return getattr(importlib.import_module(f"rllab.{component}"), name)


def sample(symbol: str, case: str) -> Any:
    """A type folder's sample, decoded into the contract type."""
    return decode(contract_symbol(symbol), raw(symbol, case))


def module(symbol: str) -> types.ModuleType:
    """The folder's double or fake module, imported by its own name."""
    (path,) = (p for p in folder(symbol).glob("*.py") if not p.name.startswith("test_"))
    for entry in (str(ROOT), str(path.parent)):
        if entry not in sys.path:
            sys.path.insert(0, entry)
    return importlib.import_module(path.stem)


def ref(text: str) -> Any:
    """``"<symbol>/<case>"``: the double that case loads, or the decoded sample."""
    symbol, case = text.split("/", 1)
    has_module = any(not p.name.startswith("test_") for p in folder(symbol).glob("*.py"))
    return module(symbol).load(case) if has_module else sample(symbol, case)


# ------------------------------------------------------------------------- JSON Schema
def validate(instance: Any, spec: Mapping[str, Any], root: Mapping[str, Any] | None = None) -> list[str]:
    """Errors of ``instance`` against ``spec``: $ref/$defs, anyOf, type, enum, const, bounds,
    properties, required, additionalProperties, items, prefixItems, minItems, maxItems."""
    return _check(instance, spec, root or spec, "$")


def _check(value: Any, spec: Mapping[str, Any], root: Mapping[str, Any], at: str) -> list[str]:
    if "$ref" in spec:
        return _check(value, root["$defs"][spec["$ref"].removeprefix("#/$defs/")], root, at)
    if "anyOf" in spec:
        if all(_check(value, option, root, at) for option in spec["anyOf"]):
            return [f"{at}: matches no anyOf option"]
        return []
    if "type" in spec and not _is_type(value, spec["type"]):
        return [f"{at}: expected {spec['type']}, got {type(value).__name__}"]
    errors = _scalar_errors(value, spec, at)
    if isinstance(value, dict):
        errors += _object_errors(value, spec, root, at)
    if isinstance(value, list):
        errors += _array_errors(value, spec, root, at)
    return errors


def _is_type(value: Any, names: str | list[str]) -> bool:
    for name in [names] if isinstance(names, str) else names:
        if isinstance(value, bool) and name in {"integer", "number"}:
            continue
        if isinstance(value, _JSON_TYPES[name]):
            return True
    return False


def _scalar_errors(value: Any, spec: Mapping[str, Any], at: str) -> list[str]:
    errors = []
    if "enum" in spec and value not in spec["enum"]:
        errors.append(f"{at}: {value!r} not in {spec['enum']}")
    if "const" in spec and value != spec["const"]:
        errors.append(f"{at}: {value!r} != {spec['const']!r}")
    number = isinstance(value, (int, float)) and not isinstance(value, bool)
    if number and "minimum" in spec and value < spec["minimum"]:
        errors.append(f"{at}: {value} < {spec['minimum']}")
    if number and "maximum" in spec and value > spec["maximum"]:
        errors.append(f"{at}: {value} > {spec['maximum']}")
    if number and "exclusiveMinimum" in spec and value <= spec["exclusiveMinimum"]:
        errors.append(f"{at}: {value} <= {spec['exclusiveMinimum']}")
    return errors


def _object_errors(
    value: dict[str, Any], spec: Mapping[str, Any], root: Mapping[str, Any], at: str
) -> list[str]:
    errors = [f"{at}: missing {key!r}" for key in spec.get("required", []) if key not in value]
    properties, extra = spec.get("properties", {}), spec.get("additionalProperties", True)
    for key, item in value.items():
        if key in properties:
            errors += _check(item, properties[key], root, f"{at}.{key}")
        elif extra is False:
            errors.append(f"{at}: unexpected {key!r}")
        elif isinstance(extra, dict):
            errors += _check(item, extra, root, f"{at}.{key}")
    return errors


def _array_errors(
    value: list[Any], spec: Mapping[str, Any], root: Mapping[str, Any], at: str
) -> list[str]:
    errors = []
    if len(value) < spec.get("minItems", 0):
        errors.append(f"{at}: fewer than {spec['minItems']} items")
    if len(value) > spec.get("maxItems", math.inf):
        errors.append(f"{at}: more than {spec['maxItems']} items")
    prefix = spec.get("prefixItems", [])
    for i, item in enumerate(value):
        item_spec = prefix[i] if i < len(prefix) else spec.get("items")
        if item_spec is not None:
            errors += _check(item, item_spec, root, f"{at}[{i}]")
    return errors


# ------------------------------------------------------------------- encode and decode
def encode(value: Any) -> Any:
    """A contract value as JSON data: dataclasses as objects, arrays as nested lists, paths
    and datetimes as strings, timedeltas as seconds."""
    if dataclasses.is_dataclass(value) and not isinstance(value, type):
        return {f.name: encode(getattr(value, f.name)) for f in dataclasses.fields(value)}
    if isinstance(value, np.ndarray):
        return value.tolist()
    if isinstance(value, np.generic):
        return value.item()
    if isinstance(value, Mapping):
        return {str(k): encode(v) for k, v in value.items()}
    if isinstance(value, (tuple, list)):
        return [encode(v) for v in value]
    if isinstance(value, Path):
        return value.as_posix()
    if isinstance(value, datetime):
        return value.isoformat()
    if isinstance(value, timedelta):
        return value.total_seconds()
    return value


def decode(tp: Any, data: Any) -> Any:
    """JSON data as a value of type ``tp``: the inverse of ``encode``. Float arrays become
    float32 (``core.Step``'s dtype), int arrays int64, bool arrays bool."""
    origin, args = typing.get_origin(tp), typing.get_args(tp)
    if tp is Any or tp is object:
        return data
    if origin in {typing.Union, types.UnionType}:
        return _decode_union(args, data)
    if origin is typing.Literal:
        if data not in args:
            raise ValueError(f"{data!r} not in {args}")
        return data
    if origin is np.ndarray:
        array = np.asarray(data)
        return array.astype(np.float32) if array.dtype == np.float64 else array
    if origin in {Mapping, dict}:
        return {k: decode(args[1], v) for k, v in data.items()} if args else dict(data)
    if origin is tuple:
        if len(args) == 2 and args[1] is Ellipsis:
            return tuple(decode(args[0], v) for v in data)
        return tuple(decode(a, v) for a, v in zip(args, data, strict=True))
    if origin is list:
        return [decode(args[0], v) for v in data]
    if dataclasses.is_dataclass(tp):
        return _decode_dataclass(tp, data)
    return _decode_scalar(tp, data)


def _decode_union(args: tuple[Any, ...], data: Any) -> Any:
    if data is None and type(None) in args:
        return None
    options = [a for a in args if a is not type(None)]
    if len(options) == 1:
        return decode(options[0], data)
    for option in options:
        if dataclasses.is_dataclass(option) and isinstance(data, dict):
            if set(data) == {f.name for f in dataclasses.fields(option)}:
                return decode(option, data)
        elif isinstance(option, type) and isinstance(data, option):
            return data
    raise ValueError(f"{data!r} matches none of {options}")


def _decode_dataclass(tp: Any, data: Mapping[str, Any]) -> Any:
    hints = typing.get_type_hints(tp)
    names = {f.name for f in dataclasses.fields(tp)}
    if extra := set(data) - names:
        raise ValueError(f"{tp.__name__} has no field {sorted(extra)}")
    return tp(**{k: decode(hints[k], v) for k, v in data.items()})


def _decode_scalar(tp: Any, data: Any) -> Any:
    if tp is Path:
        return Path(data)
    if tp is datetime:
        return datetime.fromisoformat(data)
    if tp is timedelta:
        return timedelta(seconds=data)
    if tp is float and isinstance(data, (int, float)) and not isinstance(data, bool):
        return float(data)
    if isinstance(tp, type) and isinstance(data, tp):
        return data
    raise ValueError(f"{data!r} is not a {tp}")


def same_json(a: Any, b: Any) -> bool:
    """Equal JSON data, floats to float32 precision and NaN equal to NaN."""
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(same_json(a[k], b[k]) for k in a)
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(same_json(x, y) for x, y in zip(a, b, strict=True))
    if isinstance(a, float) or isinstance(b, float):
        both = isinstance(a, (int, float)) and isinstance(b, (int, float))
        return both and (math.isclose(a, b, rel_tol=1e-6, abs_tol=1e-7) or a != a and b != b)
    return type(a) is type(b) and a == b


# --------------------------------------------------------------------- replay doubles
class ReplayPolicy:
    """A ``core.Policy`` replaying recorded (observation, action) pairs: ``act`` answers a
    recorded observation with its recorded action and refuses any other."""

    def __init__(self, pairs: Sequence[tuple[core.Array, core.Array]]) -> None:
        self.pairs = list(pairs)
        self.seen: list[core.Array] = []

    def act(self, obs: core.Array, rng: np.random.Generator) -> core.Array:
        self.seen.append(obs)
        for recorded, action in self.pairs:
            if recorded.shape == obs.shape and np.allclose(recorded, obs):
                return action.copy()
        raise KeyError(f"observation not in the recording: {obs.tolist()}")


class ReplayWorld:
    """A ``core.World`` replaying one recorded episode from every seed.

    ``reset`` returns the recorded first step whatever the seed; ``step`` checks the action
    format (``ActionError`` naming the agent, never clipping), ignores which valid action it
    got, and returns the next recorded step; a step after ``done`` raises ``RuntimeError``.
    """

    def __init__(self, recording: Mapping[str, Any]) -> None:
        self.spec: core.WorldSpec = decode(core.WorldSpec, recording["spec"])
        self.steps: list[core.Step] = [decode(core.Step, s) for s in recording["steps"]]
        self.draws: list[core.DrawState] = [decode(core.DrawState, d) for d in recording["draws"]]
        self.actions: list[core.Array] = [decode(core.Array, a) for a in recording["actions"]]
        self.recorded_result: core.EpisodeResult = decode(core.EpisodeResult, recording["result"])
        self.t = -1
        self.seed = self.recorded_result.seed

    def reset(self, seed: int) -> core.Step:
        self.t, self.seed = 0, seed
        return self.steps[0]

    def step(self, actions: core.Array) -> core.Step:
        if self.t < 0 or self.steps[self.t].done:
            raise RuntimeError("step called before reset or after the episode ended")
        for i, row in enumerate(np.asarray(actions).reshape(len(self.spec.agents), -1)):
            if self.steps[self.t].active[i] and not _in_space(row, self.spec.action):
                raise core.ActionError(self.spec.agents[i], row.tolist())
        self.t += 1
        return self.steps[self.t]

    def result(self) -> core.EpisodeResult:
        return dataclasses.replace(self.recorded_result, seed=self.seed, length=self.t)

    def draw(self) -> core.DrawState:
        return self.draws[max(self.t, 0)]


def _in_space(row: core.Array, space: core.ActionSpace) -> bool:
    if isinstance(space, core.Discrete):
        return row.size == 1 and float(row[0]).is_integer() and 0 <= row[0] < space.n
    return row.size == space.dims and bool(np.all((row >= space.low) & (row <= space.high)))

