"""Tiny simulators used only to generate consistent contract recordings."""

import numpy as np

from rllab.core import Drawable, DrawState, Step

HEAD = [(0, -1), (1, 0), (0, 1), (-1, 0)]  # up right down left
F32 = np.float32


class SnakeSim:
    def __init__(self, seed, max_steps):
        self.rng = np.random.default_rng(seed)
        self.body = [(5, 5), (5, 6), (5, 7)]
        self.heading = 0
        self.food = self._place()
        self.t = 0
        self.eaten = 0
        self.hunger = 0
        self.total = 0.0
        self.done = False
        self.max_steps = max_steps

    def _place(self):
        free = [(x, y) for y in range(10) for x in range(10) if (x, y) not in self.body]
        return free[int(self.rng.integers(len(free)))]

    def blocked(self, cell):
        x, y = cell
        return not (0 <= x < 10 and 0 <= y < 10) or cell in self.body[:-1]

    def ahead(self, h):
        dx, dy = HEAD[h]
        hx, hy = self.body[0]
        return (hx + dx, hy + dy)

    def obs(self):
        h = self.heading
        danger = [
            self.blocked(self.ahead(h)),
            self.blocked(self.ahead((h - 1) % 4)),
            self.blocked(self.ahead((h + 1) % 4)),
        ]
        heading = [1.0 if i == h else 0.0 for i in range(4)]
        hx, hy = self.body[0]
        fx, fy = self.food
        food = [fy < hy, fx > hx, fy > hy, fx < hx]
        return np.array([[float(v) for v in danger + heading + food] + [float(len(self.body))]], F32)

    def reset_step(self):
        return Step(self.obs(), np.zeros(1, F32), np.ones(1, bool), False, False)

    def step(self, action):
        h = {0: (self.heading - 1) % 4, 1: (self.heading + 1) % 4, 2: self.heading}[action]
        self.heading = h
        nxt = self.ahead(h)
        self.t += 1
        reward = 0.0
        if self.blocked(nxt):
            self.done = True
            reward = -1.0
        else:
            self.body.insert(0, nxt)
            if nxt == self.food:
                self.eaten += 1
                reward = 1.0
                self.hunger = 0
                self.food = self._place()
            else:
                self.body.pop()
                self.hunger += 1
            if self.hunger >= 100:
                self.done = True
        truncated = not self.done and self.t >= self.max_steps
        self.done = self.done or truncated
        self.total += reward
        return Step(self.obs(), np.array([reward], F32), np.ones(1, bool), self.done, truncated)

    def draw(self):
        (hx, hy), rest = self.body[0], self.body[1:]
        objs = [Drawable("head", float(hx), float(hy), 1.0, "snake", 0)]
        objs += [Drawable("body", float(x), float(y), 1.0, "snake", None) for x, y in rest]
        objs.append(Drawable("food", float(self.food[0]), float(self.food[1]), 1.0, None, None))
        return DrawState(10.0, 10.0, tuple(objs))

    def _relative(self, d):
        if d == self.heading:
            return 2
        if d == (self.heading - 1) % 4:
            return 0
        if d == (self.heading + 1) % 4:
            return 1
        return None

    def rule(self):
        hx, hy = self.body[0]
        fx, fy = self.food
        dx, dy = fx - hx, fy - hy
        wanted = []
        for dist, axis in sorted([(abs(dx), "x"), (abs(dy), "y")]):
            if dist == 0:
                continue
            if axis == "x":
                wanted.append(1 if dx > 0 else 3)
            else:
                wanted.append(2 if dy > 0 else 0)
        for d in [*wanted, self.heading, (self.heading - 1) % 4, (self.heading + 1) % 4]:
            action = self._relative(d)
            if action is not None and not self.blocked(self.ahead(d)):
                return action
        return 2

