"""JSON Schema from contract types, plus writing a folder (generation only)."""

import dataclasses
import json
import math
import types
import typing
from collections.abc import Mapping
from datetime import datetime, timedelta
from pathlib import Path
from typing import Any

import numpy as np

ROOT = Path(__file__).resolve().parents[1]
ARRAY = {
    "type": "array",
    "items": {"anyOf": [{"type": ["number", "boolean"]}, {"$ref": "#/$defs/Array"}]},
}
SCALARS = {
    str: {"type": "string"},
    Path: {"type": "string"},
    datetime: {"type": "string", "format": "date-time"},
    timedelta: {"type": "number", "minimum": 0},
    bool: {"type": "boolean"},
    int: {"type": "integer"},
    float: {"type": "number"},
}
PATCH = {
    ("Discrete", "n"): {"minimum": 1},
    ("Box", "dims"): {"minimum": 1},
    ("WorldSpec", "obs_len"): {"minimum": 1},
    ("WorldSpec", "max_steps"): {"minimum": 1},
    ("EpisodeResult", "length"): {"minimum": 0},
    ("Frame", "step"): {"minimum": 0},
    ("RunConfig", "budget"): {"minimum": 1},
    ("RunConfig", "seed"): {"minimum": 0},
    ("CheckResult", "agreement"): {"minimum": 0, "maximum": 1},
    ("Checkpoint", "pct"): {"enum": list(range(0, 101, 10))},
    ("Checkpoint", "step"): {"minimum": 0},
    ("EvalPoint", "step"): {"minimum": 0},
    ("Failure", "step"): {"minimum": 0},
    ("Progress", "step"): {"minimum": 0},
    ("Progress", "budget"): {"minimum": 1},
    ("Comparison", "p_raw"): {"minimum": 0, "maximum": 1},
    ("Comparison", "p_holm"): {"minimum": 0, "maximum": 1},
    ("Verdict", "runs_needed"): {"minimum": 0},
}


def schema_of(tp: Any, defs: dict[str, Any]) -> dict[str, Any]:
    if tp is Any or tp is object:
        return {}
    origin, args = typing.get_origin(tp), typing.get_args(tp)
    if origin in {typing.Union, types.UnionType}:
        return {"anyOf": [schema_of(a, defs) for a in args]}
    if origin is typing.Literal:
        return {"enum": list(args)}
    if origin is np.ndarray:
        defs.setdefault("Array", ARRAY)
        return {"$ref": "#/$defs/Array"}
    if origin in {Mapping, dict}:
        if args[1] is object:
            return {"type": "object"}
        return {"type": "object", "additionalProperties": schema_of(args[1], defs)}
    if origin is tuple:
        if len(args) == 2 and args[1] is Ellipsis:
            return {"type": "array", "items": schema_of(args[0], defs)}
        n = len(args)
        items = [schema_of(a, defs) for a in args]
        return {"type": "array", "prefixItems": items, "minItems": n, "maxItems": n}
    if origin is list:
        return {"type": "array", "items": schema_of(args[0], defs)}
    if dataclasses.is_dataclass(tp):
        return _dataclass(tp, defs)
    if tp is type(None):
        return {"type": "null"}
    return dict(SCALARS[tp])


def _dataclass(tp: Any, defs: dict[str, Any]) -> dict[str, Any]:
    name = tp.__name__
    if name not in defs:
        defs[name] = {}
        hints = typing.get_type_hints(tp)
        fields = dataclasses.fields(tp)
        props = {f.name: schema_of(hints[f.name], defs) | PATCH.get((name, f.name), {}) for f in fields}
        required = [f.name for f in fields if f.default is dataclasses.MISSING]
        defs[name] = {
            "type": "object",
            "properties": props,
            "required": required,
            "additionalProperties": False,
        }
    return {"$ref": f"#/$defs/{name}"}


def obj(props: dict[str, Any]) -> dict[str, Any]:
    return {
        "type": "object",
        "properties": props,
        "required": list(props),
        "additionalProperties": False,
    }


def top(title: str, body: dict[str, Any], defs: dict[str, Any]) -> dict[str, Any]:
    out = {"$schema": "https://json-schema.org/draft/2020-12/schema", "title": title}
    out |= body
    if defs:
        out["$defs"] = dict(sorted(defs.items()))
    return out


def type_schema(title: str, tp: Any) -> dict[str, Any]:
    defs: dict[str, Any] = {}
    return top(title, schema_of(tp, defs), defs)


def tidy(value: Any) -> Any:
    if isinstance(value, dict):
        return {k: tidy(v) for k, v in value.items()}
    if isinstance(value, list):
        return [tidy(v) for v in value]
    if isinstance(value, float) and math.isfinite(value):
        return float(f"{value:.6g}")
    return value


def dumps(value: Any, indent: int = 0) -> str:
    pad = " " * indent
    flat = lambda v: not isinstance(v, (dict, list))  # noqa-free: generation only
    if isinstance(value, dict):
        if not value:
            return "{}"
        items = [f"{pad} {json.dumps(k)}: {dumps(v, indent + 1)}" for k, v in value.items()]
        return "{\n" + ",\n".join(items) + "\n" + pad + "}"
    if isinstance(value, list):
        if all(flat(v) for v in value):
            return json.dumps(value)
        if all(isinstance(v, list) and all(flat(x) for x in v) for v in value):
            rows = [f"{pad} {json.dumps(v)}" for v in value]
            return "[\n" + ",\n".join(rows) + "\n" + pad + "]"
        items = [f"{pad} {dumps(v, indent + 1)}" for v in value]
        return "[\n" + ",\n".join(items) + "\n" + pad + "]"
    return json.dumps(value)


def write(symbol: str, schema: dict[str, Any], samples: dict[str, Any], encode: Any) -> None:
    folder = ROOT / symbol
    (folder / "samples").mkdir(parents=True, exist_ok=True)
    (folder / "schema.json").write_text(dumps(schema) + "\n", encoding="utf-8")
    for case, value in samples.items():
        text = dumps(tidy(encode(value))) + "\n"
        (folder / "samples" / f"{case}.json").write_text(text, encoding="utf-8")

