"""worlds.CheckWorld replay doubles: the 6-state two-exit corridor and the 1-D target point.

Each replays one recorded episode (``core.World`` behaviour of ``contract_io.ReplayWorld``)
and serves its recorded ``states()`` and ``best_actions()`` (AD-09).
"""

from typing import Any

import contract_io

from rllab.core import Array


class CheckWorldDouble(contract_io.ReplayWorld):
    def __init__(self, recording: dict[str, Any]) -> None:
        super().__init__(recording)
        self.recorded_states: Array = contract_io.decode(Array, recording["states"])
        self.recorded_best: Array = contract_io.decode(Array, recording["best_actions"])

    def states(self) -> Array:
        return self.recorded_states.copy()

    def best_actions(self) -> Array:
        return self.recorded_best.copy()


def load(case: str = "corridor") -> CheckWorldDouble:
    return CheckWorldDouble(contract_io.raw("worlds.CheckWorld", case))

