"""baselines.RandomPolicy replay double: 5 snake actions and 5 fish pushes from ``rng`` seed 0.

``act`` returns the next recorded action of its case whatever the observation, so a consumer
can check what it does with uniform random actions of the declared format.
"""

from typing import Any

import contract_io
import numpy as np

from rllab.core import ActionSpace, Array


class RandomPolicyDouble:
    def __init__(self, recording: dict[str, Any]) -> None:
        self.action: ActionSpace = contract_io.decode(ActionSpace, recording["action"])
        self.actions: list[Array] = [contract_io.decode(Array, a) for a in recording["actions"]]
        self.calls = 0

    def act(self, obs: Array, rng: np.random.Generator) -> Array:
        action = self.actions[self.calls]
        self.calls += 1
        return action.copy()


