"""methods.Learner replay double: a DQN learner over 10 snake transitions.

The recording is two plays of the ``core.World`` double's seed-42 episode, so the double
answers every observation that world shows. ``act`` returns the recorded exploring action for
a recorded observation (``KeyError`` otherwise); ``observe`` keeps each transition in
``observed``; ``policy()`` is a frozen greedy ``core.Policy`` over the recorded observations;
``state_dict()`` is the recorded state.
"""

import copy
from typing import Any

import contract_io
import numpy as np

from rllab.core import Array, Policy
from rllab.methods import Transition


def _pairs(rows: list[dict[str, Any]]) -> list[tuple[Array, Array]]:
    return [(contract_io.decode(Array, r["obs"]), contract_io.decode(Array, r["action"])) for r in rows]


class LearnerDouble:
    def __init__(self, recording: dict[str, Any]) -> None:
        self.team: str = recording["team"]
        self.exploring = contract_io.ReplayPolicy(_pairs(recording["acts"]))
        self.greedy = _pairs(recording["greedy"])
        self.transitions: list[Transition] = [
            contract_io.decode(Transition, t) for t in recording["transitions"]
        ]
        self.state: dict[str, object] = recording["state"]
        self.observed: list[Transition] = []

    def act(self, obs: Array, rng: np.random.Generator) -> Array:
        return self.exploring.act(obs, rng)

    def observe(self, t: Transition) -> None:
        self.observed.append(t)

    def policy(self) -> Policy:
        return contract_io.ReplayPolicy(self.greedy)

    def state_dict(self) -> dict[str, object]:
        return copy.deepcopy(self.state)


def load(case: str = "snake_dqn") -> LearnerDouble:
    return LearnerDouble(contract_io.raw("methods.Learner", case))

