"""runlog.Run replay double: the finished 3-checkpoint snake run folder ``snake-s1``.

``record`` is the finished ``RunRecord``; ``episodes()``, ``evals()`` (21 points, 0% to 100%)
and ``checkpoints()`` (0%, 50%, 100%) are the recorded logs. ``renamed`` gives the same run under
another name, seed and status, for lookups that need several runs.
"""

import dataclasses
from typing import Any

import contract_io

from rllab.core import EpisodeResult
from rllab.runlog import Checkpoint, EvalPoint, RunRecord, RunStatus


class RunDouble:
    def __init__(self, recording: dict[str, Any]) -> None:
        self.record: RunRecord = contract_io.decode(RunRecord, recording["record"])
        self.recorded_episodes = [contract_io.decode(EpisodeResult, e) for e in recording["episodes"]]
        self.recorded_evals = [contract_io.decode(EvalPoint, e) for e in recording["evals"]]
        self.recorded_checkpoints = [contract_io.decode(Checkpoint, c) for c in recording["checkpoints"]]

    def episodes(self) -> list[EpisodeResult]:
        return list(self.recorded_episodes)

    def evals(self) -> list[EvalPoint]:
        return list(self.recorded_evals)

    def checkpoints(self) -> list[Checkpoint]:
        return list(self.recorded_checkpoints)


def load(case: str = "finished_snake") -> RunDouble:
    return RunDouble(contract_io.raw("runlog.Run", case))


def renamed(run: RunDouble, name: str, seed: int, status: RunStatus = "finished") -> RunDouble:
    config = dataclasses.replace(run.record.config, name=name, seed=seed)
    ended = run.record.ended if status in {"finished", "failed"} else None
    path = run.record.path.parent / name
    run.record = dataclasses.replace(run.record, config=config, status=status, ended=ended, path=path)
    run.recorded_checkpoints = [
        dataclasses.replace(c, run=name, path=path / c.path.relative_to(c.path.parents[1]))
        for c in run.recorded_checkpoints
    ]
    return run

