``RunWriterDouble`` has ``RunWriter``'s constructor and methods: it keeps every call in
``calls`` (as recorded JSON), touches no disk except to refuse an existing run folder with
``RunExistsError``, and returns the ``Checkpoint`` and ``RunRecord`` the real writer would, with
the recorded start and end times. ``replay_into(writer)`` drives any ``RunWriter`` through the
recorded calls and returns what its ``close`` returns.
"""

from collections.abc import Mapping
from pathlib import Path
from typing import Any

import contract_io

from rllab.core import EpisodeResult, RunConfig, WorldSpec
from rllab.runlog import Checkpoint, EvalPoint, Failure, RunExistsError, RunRecord, RunWriter

RECORDING = contract_io.raw("runlog.RunWriter", "snake_3_checkpoints")


class RunWriterDouble:
    def __init__(self, root: Path, config: RunConfig, spec: WorldSpec) -> None:
        self.path = root / config.world / config.variant / config.name
        if self.path.exists():
            raise RunExistsError(self.path)
        self.config, self.spec = config, spec
        self.calls: list[dict[str, Any]] = []

    def episode(self, result: EpisodeResult) -> None:
        self.calls.append({"call": "episode", "result": contract_io.encode(result)})

    def eval(self, point: EvalPoint) -> None:
        self.calls.append({"call": "eval", "point": contract_io.encode(point)})

    def checkpoint(self, pct: int, step: int, state: Mapping[str, dict[str, object]]) -> Checkpoint:
        self.calls.append({"call": "checkpoint", "pct": pct, "step": step, "state": contract_io.encode(state)})
        ckpt_path = self.path / "checkpoints" / f"ckpt_{pct}.pt"
        return Checkpoint(self.config.name, pct, step, self.spec, self.config.methods, dict(state), ckpt_path)

    def close(self, status: str, failure: Failure | None = None) -> RunRecord:
        self.calls.append({"call": "close", "status": status, "failure": contract_io.encode(failure)})
        started, ended = (contract_io.decode(RunRecord.__annotations__["started"], RECORDING[k]) for k in ("started", "ended"))
        return contract_io.decode(
            RunRecord,
            contract_io.encode(
                {"config": self.config, "spec": self.spec, "started": started, "ended": ended,
                 "status": status, "failure": failure, "path": self.path}
            ),
        )


def writer(root: Path) -> RunWriterDouble:
    """A double opened with the recorded config and spec under ``root``."""
    config = contract_io.decode(RunConfig, RECORDING["config"])
    return RunWriterDouble(root, config, contract_io.decode(WorldSpec, RECORDING["spec"]))


def replay_into(target: RunWriter | RunWriterDouble) -> RunRecord:
    """Make the recorded calls on ``target``; the record its ``close`` returns."""
    record = None
    for call in RECORDING["calls"]:
        kind = call["call"]
        if kind == "episode":
            target.episode(contract_io.decode(EpisodeResult, call["result"]))
        elif kind == "eval":
            target.eval(contract_io.decode(EvalPoint, call["point"]))
        elif kind == "checkpoint":
            target.checkpoint(call["pct"], call["step"], call["state"])
        else:
            failure = contract_io.decode(Failure | None, call["failure"])
            record = target.close(call["status"], failure)
    if record is None:
        raise AssertionError("the recording has no close call")
    return record

