"""Every contract sample validates against its schema and decodes into its contract type."""

import dataclasses
import importlib
import sys
import types
from pathlib import Path

import pytest

sys.path.insert(0, str(Path(__file__).parent))
contract_io = importlib.import_module("contract_io")

import rllab.core as core  # noqa-free import after the path setup is fine: rllab is installed

ALL = [(s, c) for s in contract_io.symbols() for c in contract_io.cases(s)]


def _is_type(symbol: str) -> bool:
    obj = contract_io.contract_symbol(symbol)
    return dataclasses.is_dataclass(obj) or isinstance(obj, types.UnionType)


TYPED = [(s, c) for s, c in ALL if _is_type(s)]


def test_every_folder_has_a_schema_and_a_sample():
    for symbol in contract_io.symbols():
        assert (contract_io.folder(symbol) / "schema.json").is_file(), symbol
        assert contract_io.cases(symbol), symbol


@pytest.mark.parametrize(("symbol", "case"), ALL, ids=[f"{s}/{c}" for s, c in ALL])
def test_sample_validates_against_its_schema(symbol, case):
    assert contract_io.validate(contract_io.raw(symbol, case), contract_io.schema(symbol)) == []


@pytest.mark.parametrize(("symbol", "case"), TYPED, ids=[f"{s}/{c}" for s, c in TYPED])
def test_schema_rejects_a_sample_missing_a_field(symbol, case):
    data = contract_io.raw(symbol, case)
    broken = {k: v for k, v in data.items() if k != next(iter(data))}
    assert contract_io.validate(broken, contract_io.schema(symbol)) != []


@pytest.mark.parametrize(("symbol", "case"), TYPED, ids=[f"{s}/{c}" for s, c in TYPED])
def test_sample_decodes_into_its_type_and_back(symbol, case):
    value = contract_io.sample(symbol, case)
    tp = contract_io.contract_symbol(symbol)
    options = tp.__args__ if isinstance(tp, types.UnionType) else (tp,)
    assert isinstance(value, options)
    assert contract_io.same_json(contract_io.encode(value), contract_io.raw(symbol, case))


@pytest.mark.parametrize(
    ("symbol", "seeds", "count"),
    [("core.EVAL_SEEDS", core.EVAL_SEEDS, 20), ("core.FINAL_SEEDS", core.FINAL_SEEDS, 100)],
)
def test_seed_sets_are_the_listed_seeds(symbol, seeds, count):
    assert seeds == tuple(contract_io.raw(symbol, "seeds"))
    assert len(set(seeds)) == count
    assert min(seeds) >= 1_000_000  # disjoint from the training seeds [0, 10^6)


def test_seed_sets_are_disjoint():
    assert not set(core.EVAL_SEEDS) & set(core.FINAL_SEEDS)


def test_step_samples_hold_one_row_per_agent():
    for case in contract_io.cases("core.Step"):
        step = contract_io.sample("core.Step", case)
        assert step.obs.dtype == "float32"
        assert step.rewards.dtype == "float32"
        assert step.active.dtype == bool
        assert step.obs.shape[0] == step.rewards.shape[0] == step.active.shape[0]
        assert not step.obs[~step.active].any()
        assert not step.rewards[~step.active].any()


def test_world_spec_teams_cover_every_agent_once():
    for case in contract_io.cases("core.WorldSpec"):
        spec = contract_io.sample("core.WorldSpec", case)
        members = sorted(i for team in spec.teams for i in team.agents)
        assert members == list(range(len(spec.agents))), case
        assert {m.team for m in spec.measures} <= {t.name for t in spec.teams}


def test_traced_episode_has_one_frame_more_than_its_length():
    traced = contract_io.sample("core.Episode", "corridor_traced_3")
    assert len(traced.frames) == traced.result.length + 1
    assert contract_io.sample("core.Episode", "snake_untraced").frames is None


def test_frame_zero_is_the_reset_state_with_zero_rewards():
    frame = contract_io.sample("core.Frame", "snake_seed7_frame0")
    assert frame.step == 0
    assert not frame.rewards.any()


def test_check_results_pass_at_095_agreement():
    for case in contract_io.cases("train.CheckResult"):
        result = contract_io.sample("train.CheckResult", case)
        assert result.passed == (result.agreement >= 0.95)


def test_summary_samples_follow_the_run_count_rule():
    for case in contract_io.cases("evaluate.Summary"):
        summary = contract_io.sample("evaluate.Summary", case)
        means = list(summary.run_means.values())
        assert summary.learned_mean == pytest.approx(sum(means) / len(means))
        assert summary.learned_range == (min(means), max(means))
        if len(summary.runs) < 5:
            assert summary.comparisons == ()
            assert summary.verdict.runs_needed > 0
        else:
            assert summary.verdict.runs_needed == 0


def test_comparison_difference_is_signed_toward_better():
    for case in contract_io.cases("evaluate.Comparison"):
        c = contract_io.sample("evaluate.Comparison", case)
        assert c.difference == pytest.approx(c.learned_mean - c.baseline_mean)
        assert c.p_holm >= c.p_raw

