def folder(symbol: str) -> Path:
    """The folder of ``symbol``. ``runlog.progress`` and ``runlog.Progress`` are one folder on a
    case-insensitive filesystem, so a missing exact name falls back to a case-insensitive match."""
    exact = ROOT / symbol
    if exact.is_dir():
        return exact
    return next((p for p in ROOT.iterdir() if p.name.lower() == symbol.lower()), exact)

